  template <typename T, typename... Args>
  T *fork(Args &&...args) {
    T *const listener = new T(args...);
    listener->m_session = m_session;
    listener->m_fileContent = m_fileContent;
    listener->m_compiler = m_compiler;
    return listener;
  }

