  [[nodiscard]] AstNode getNodeChild(const AstNode &node) const;
  [[nodiscard]] AstNode getNodeChild(const AstNode &node, VObjectType type) const;
  [[nodiscard]] AstNode getNodeChild(const AstNode &node, const std::set<VObjectType> &types) const;

  [[nodiscard]] AstNodeIterationHelper getNodeChildren(const AstNode &node) const {
    return AstNodeIterationHelper(this, getNodeChild(node), {});
  }
  [[nodiscard]] AstNodeIterationHelper getNodeChildren(const AstNode &node, VObjectType type) const {
    return AstNodeIterationHelper(this, getNodeChild(node, type), {type});
  }
  [[nodiscard]] AstNodeIterationHelper getNodeChildren(const AstNode &node, const std::set<VObjectType> &types) const {
    return AstNodeIterationHelper(this, getNodeChild(node, types), types);
  }

  [[nodiscard]] AstNodeIterationHelper getNodeNextSiblings(const AstNode &node) const {
    return AstNodeIterationHelper(this, node, {});
  }
  [[nodiscard]] AstNodeIterationHelper getNodeNextSiblings(const AstNode &node, VObjectType type) const {
    const AstNode firstNode = (getNodeType(node) == type) ? node : getNodeNextSibling(node, type);
    return AstNodeIterationHelper(this, firstNode, {type});
  }
  [[nodiscard]] AstNodeIterationHelper getNodeNextSiblings(const AstNode &node, const std::set<VObjectType> &types) const {
    const AstNode firstNode = (types.find(getNodeType(node)) != types.cend()) ? node : getNodeNextSibling(node, types);
    return AstNodeIterationHelper(this, firstNode, types);
  }

  [[nodiscard]] bool getNodeChildren(const AstNode &node, astnode_vector_t &children) const;
  [[nodiscard]] bool getNodeSiblings(const AstNode &node, astnode_vector_t &siblings) const;

